-- public.set_active_thread
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
insert into auth.users (id, email) values ('11111111-1111-1111-1111-111111111111','u1@example.test'),('22222222-2222-2222-2222-222222222222','u2@example.test');
insert into public.teams (id, name, sport, season_label) values ('e1000000-0000-0000-0000-000000000001','T1','soccer','Fall');
insert into public.team_memberships (team_id, profile_id, role) values ('e1000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','admin'),('e1000000-0000-0000-0000-000000000001','22222222-2222-2222-2222-222222222222','parent');
insert into public.threads (id, team_id, type, title) values ('71000000-0000-0000-0000-00000000000b','e1000000-0000-0000-0000-000000000001','group','G');
insert into public.thread_participants (thread_id, profile_id, role) values ('71000000-0000-0000-0000-00000000000b','22222222-2222-2222-2222-222222222222','member');
delete from public.notification_outbox;
insert into public.push_devices (profile_id, platform, token) values ('22222222-2222-2222-2222-222222222222','ios','ExponentPushToken[aaaaaaaaaa]'),('11111111-1111-1111-1111-111111111111','ios','ExponentPushToken[bbbbbbbbbb]');
set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select public.set_active_thread('ExponentPushToken[aaaaaaaaaa]','71000000-0000-0000-0000-00000000000b') $$, '42501', null, 'anonymous cannot call');
reset role; select set_config('request.jwt.claims', '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.set_active_thread('ExponentPushToken[aaaaaaaaaa]','71000000-0000-0000-0000-00000000000b') $$, 'a participant marks the thread open');
reset role;
select is((select active_thread_id::text from public.push_devices where token='ExponentPushToken[aaaaaaaaaa]'), '71000000-0000-0000-0000-00000000000b', 'stored');
reset role; select set_config('request.jwt.claims', '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select public.set_active_thread('ExponentPushToken[aaaaaaaaaa]', null);
reset role;
select is((select active_thread_id is null from public.push_devices where token='ExponentPushToken[aaaaaaaaaa]'), true, 'cleared on close');
reset role; select set_config('request.jwt.claims', '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select public.set_active_thread('ExponentPushToken[bbbbbbbbbb]','71000000-0000-0000-0000-00000000000b');
reset role;
select is((select active_thread_id is null from public.push_devices where token='ExponentPushToken[bbbbbbbbbb]'), true, 'cannot touch another user device');
reset role; select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select public.set_active_thread('ExponentPushToken[bbbbbbbbbb]','71000000-0000-0000-0000-00000000000b') $$, '42501', null, 'cannot mark a thread you cannot read');
reset role;
select * from finish();
rollback;
